// Cross-language vectors for the endpoint trust verifier (Task20c).
// Every `NN-*.json` file under `tests/fixtures/trust/` is a case generated by
// TrackAI's `generate.ts` from fixed test keys (deterministic RFC 6979
// signatures). For every vector this harness asserts the same `status` and
// `code`, and the same `keyid`, `trusted` and `trusted_time` where the vector
// states them. See `tests/fixtures/trust/SOURCE.md` for provenance.

use std::collections::BTreeMap;
use std::fs;

use git_ai::trust::{
    ArtifactPurpose, DsseEnvelope, TimeEvidence, TrustCode, TrustState, TrustStatus, TrustVerdict,
    TrustedDocumentRef, VerifyTrustedInput,
};
use serde::Deserialize;

const EXPECTED_VECTORS: usize = 82;

#[derive(Debug, Deserialize)]
struct VectorFile {
    #[allow(dead_code)]
    vector_version: u64,
    name: String,
    #[allow(dead_code)]
    description: String,
    input: VectorInput,
    expected: VectorExpected,
}

#[derive(Debug, Deserialize)]
struct VectorInput {
    payload_type: String,
    payload_b64: String,
    envelope: DsseEnvelope,
    purpose: ArtifactPurpose,
    audience: String,
    signed_at: String,
    time_evidence: Option<TimeEvidence>,
    state: TrustState,
}

#[derive(Debug, Deserialize)]
struct VectorExpected {
    status: TrustStatus,
    code: TrustCode,
    keyid: Option<String>,
    trusted_time: Option<String>,
    trusted: Option<BTreeMap<String, TrustedDocumentRef>>,
}

fn base64_decode_strict(value: &str) -> Option<Vec<u8>> {
    use base64::Engine;
    if value.len() % 4 != 0 {
        return None;
    }
    base64::engine::general_purpose::STANDARD
        .decode(value)
        .ok()
}

#[test]
fn trust_vectors_match_typescript() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/trust");
    let mut files: Vec<_> = fs::read_dir(dir)
        .expect("fixtures dir readable")
        .map(|e| e.expect("dir entry").path())
        .filter(|p| {
            p.extension().map(|x| x == "json").unwrap_or(false)
                && p.file_name()
                    .map(|n| n.to_string_lossy().starts_with(|c: char| c.is_ascii_digit()))
                    .unwrap_or(false)
        })
        .collect();
    files.sort();
    assert_eq!(
        files.len(),
        EXPECTED_VECTORS,
        "expected {EXPECTED_VECTORS} vector files, found {}",
        files.len()
    );

    let mut failures: Vec<String> = Vec::new();
    for path in &files {
        let text = fs::read_to_string(path).expect("vector readable");
        // A vector whose input does not even deserialize is a malformed call:
        // the TypeScript verifier answers INPUT_INVALID for those.
        let parsed: Result<VectorFile, _> = serde_json::from_str(&text);
        let vector = match parsed {
            Ok(v) => v,
            Err(err) => {
                let raw: serde_json::Value =
                    serde_json::from_str(&text).expect("vector is JSON");
                let expected: VectorExpected = serde_json::from_value(
                    raw.get("expected").cloned().expect("vector has expected"),
                )
                .expect("vector expected parses");
                let name = raw
                    .get("name")
                    .and_then(|n| n.as_str())
                    .unwrap_or("unknown");
                if expected.code != TrustCode::InputInvalid {
                    failures.push(format!(
                        "{}: input failed to parse ({err}) but expected {:?}",
                        name, expected.code
                    ));
                }
                continue;
            }
        };

        let payload = match base64_decode_strict(&vector.input.payload_b64) {
            Some(p) => p,
            None => {
                failures.push(format!("{}: payload_b64 is not valid base64", vector.name));
                continue;
            }
        };
        let input = VerifyTrustedInput {
            payload_type: vector.input.payload_type,
            payload,
            envelope: vector.input.envelope,
            purpose: vector.input.purpose,
            audience: vector.input.audience,
            signed_at: vector.input.signed_at,
            time_evidence: vector.input.time_evidence,
            state: vector.input.state,
        };
        let got: TrustVerdict = git_ai::trust::verify_trusted(&input);
        let want = &vector.expected;
        let mut problems: Vec<String> = Vec::new();
        if got.status != want.status {
            problems.push(format!("status {:?} != {:?}", got.status, want.status));
        }
        if got.code != want.code {
            problems.push(format!("code {:?} != {:?}", got.code, want.code));
        }
        if let Some(keyid) = &want.keyid
            && got.keyid.as_ref() != Some(keyid)
        {
            problems.push(format!("keyid {:?} != {keyid:?}", got.keyid));
        }
        if let Some(trusted_time) = &want.trusted_time
            && got.trusted_time.as_ref() != Some(trusted_time)
        {
            problems.push(format!(
                "trusted_time {:?} != {trusted_time:?}",
                got.trusted_time
            ));
        }
        if let Some(trusted) = &want.trusted
            && got.trusted.as_ref() != Some(trusted)
        {
            problems.push(format!("trusted {:?} != {trusted:?}", got.trusted));
        }
        if !problems.is_empty() {
            failures.push(format!("{}: {}", vector.name, problems.join("; ")));
        }
    }

    assert!(
        failures.is_empty(),
        "{} vector(s) mismatched:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
